"""已有漏洞观测与直接子资产的完整性核对。"""
import json
from hep_lfx import business


async def children(value):
    common = business()
    asset = value["item"]
    targets, errors, expected, page = {asset["assetId"]: asset}, [], None, 1
    try:
        while True:
            reply = await common.request("master", "get_soc_asset_registration_children", {"assetId": asset["assetId"], "page": page})
            records, total = common.rows(reply), reply.get("data", {}).get("total")
            if type(total) is not int or total < 0 or expected is not None and expected != total:
                raise ValueError("子资产分页总数无效或变化")
            expected, before = total, len(targets)
            for child in records:
                identity = child.get("assetId")
                if type(identity) is not int or identity <= 0 or identity == asset["assetId"] or child.get("hostAssetId") != asset["assetId"]:
                    raise ValueError("子资产标识或宿主归属不一致")
                targets[identity] = child
            if len(targets) - 1 > total:
                raise ValueError("子资产返回超过声明总数")
            if len(targets) - 1 == total:
                break
            if not records or len(targets) == before:
                raise ValueError("子资产分页不完整")
            page += 1
    except Exception as error:
        errors.append(str(error))
    return {**value, "asset": asset, "items": list(targets.values()), "errors": errors}


async def observations(value):
    asset_id = value["item"]["assetId"]
    try:
        records = business().rows(await business().request("master", "get_soc_asset_vulnerabilities", {"assetId": asset_id}))
        if any(not isinstance(record, dict) for record in records):
            raise ValueError("漏洞明细不是对象")
        return {"assetId": asset_id, "observed_at": business().now(), "records": records}
    except Exception as error:
        return {"assetId": asset_id, "error": str(error)}


def assess(value):
    findings, sources, errors = {}, [], list(value["errors"])
    for source in value["items"]:
        if source.get("error"):
            errors.append("资产 " + str(source["assetId"]) + "：" + source["error"])
            continue
        sources.append({**source, "records": len(source["records"])})
        for record in source["records"]:
            identity = str(next((record[key] for key in ("id", "vulnerabilityId", "cveId") if record.get(key) is not None), json.dumps(record, sort_keys=True, ensure_ascii=False)))
            findings.setdefault(identity, {"identity": identity, "observations": []})["observations"].append({"sourceAssetId": source["assetId"], "record": record})
    ordered = []
    for identity in sorted(findings):
        finding = findings[identity]
        finding["observations"].sort(key=lambda entry: (entry["sourceAssetId"], json.dumps(entry["record"], sort_keys=True)))
        finding["sourceAssetIds"] = sorted(set(entry["sourceAssetId"] for entry in finding["observations"]))
        ordered.append(finding)
    return business().item(value["asset"], {"status": "failed" if errors else "abnormal" if findings else "unknown",
        "message": ("查询到 " + str(len(findings)) + " 条去重漏洞观测" if findings else "未返回漏洞观测") + "；不证明扫描覆盖、当前未修复数量或资产无漏洞",
        "recommendation": "核对漏洞数据来源、扫描覆盖及受影响软件的当前处置状态。", "findings": ordered,
        "sources": sorted(sources, key=lambda source: source["assetId"]), "errors": errors, "coverage": "incomplete" if errors else "existing_records_only"})
